// The four fields the brief names - sender, subject, body, thread id - plus the
// two message ids, made explicit so they are visible in this node's output
// rather than buried in the Gmail payload. Nothing downstream reads the raw
// Gmail item.
//
// Two different ids matter and they are not interchangeable:
//   id         - Gmail's own message id. Stable, unique, assigned by Google.
//                This is the idempotency key and what the reply node quotes.
//   messageId  - the RFC 5322 Message-ID header. Written by the SENDER, so a
//                sender can repeat it or forge it. Kept for the audit trail and
//                for threading in non-Gmail clients; never used as a key.
const MONEY_MARKERS = [
  'refund', 'refunded', 'chargeback', 'charge back', 'money back', 'reimburse',
  'double charged', 'charged twice', 'overcharged', 'dispute', 'credit note',
  'compensation', 'invoice me', 'cancel my subscription and refund',
];
const LEGAL_MARKERS = ['lawyer', 'solicitor', 'legal action', 'gdpr request', 'data deletion request', 'ombudsman', 'small claims'];
const ANGRY_MARKERS = ['unacceptable', 'appalling', 'furious', 'disgusted', 'worst', 'scam', 'fraud'];

const out = [];

for (const item of $input.all()) {
  const email = item.json;

  // mailparser gives from/to as { value: [{ address, name }], text }.
  const fromValue = email.from?.value?.[0] ?? {};
  const sender = String(fromValue.address || email.from?.text || '').trim().toLowerCase();
  if (!sender) throw new Error('Gmail message ' + email.id + ' has no parseable From address');

  const subject = String(email.subject || '(no subject)').trim();

  // text is the plain-text part. Falling back to stripping the HTML is not
  // cosmetic: a marketing email is often HTML-only, and an empty body would
  // classify as "unclear" and reach a human instead of being routed out.
  const body = String(
    email.text || String(email.html || '').replace(/<[^>]+>/g, ' ') || email.snippet || '',
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .trim()
    .slice(0, 8000);

  const haystack = (subject + ' ' + body).toLowerCase();
  const money = MONEY_MARKERS.filter((m) => haystack.includes(m));
  const legal = LEGAL_MARKERS.filter((m) => haystack.includes(m));
  const angry = ANGRY_MARKERS.filter((m) => haystack.includes(m));

  out.push({
    json: {
      // --- the four the brief names, plus the ids ---------------------------
      sender,
      sender_name: String(fromValue.name || '').trim() || null,
      subject,
      body,
      thread_id: String(email.threadId || ''),
      gmail_message_id: String(email.id || ''),
      rfc_message_id: String(email.messageId || '') || null,
      // --- context ----------------------------------------------------------
      received_at: email.date || new Date().toISOString(),
      label_ids: email.labelIds || [],
      decision_key: 'email:' + String(email.id || ''),
      // --- deterministic sweep ---------------------------------------------
      // Computed before the model is asked anything, so it cannot be argued
      // out of by a confident classification. It can only ADD caution.
      keyword_money: money.length > 0,
      keyword_legal: legal.length > 0,
      keyword_angry: angry.length > 0,
      keyword_hits: [...money, ...legal, ...angry].slice(0, 8),
    },
  });
}

return out;

// The Postgres node above replaced the item with its RETURNING row, so the
// email is put back. Matched by gmail_message_id rather than by position:
// when a poll delivers several messages and one of them is a duplicate, the
// claim node emits fewer rows than it received and positions no longer line up.
const captured = new Map($('Capture Email Fields').all().map((i) => [i.json.gmail_message_id, i.json]));

return $input
  .all()
  .filter((i) => i.json && i.json.gmail_message_id)
  .map((i) => ({ json: { ...captured.get(i.json.gmail_message_id), claim_id: i.json.id } }));

