={
  "model": "{{ $env.LLM_MODEL }}",
  "temperature": 0,
  "max_tokens": 300,
  "messages": [
    {
      "role": "system",
      "content": "You triage a business support inbox. Decide whether an incoming email is a genuine support request from a customer, and return JSON only.\n\nis_support is true only for a real person asking this business for help with its product, their account, an order, a bug, or how something works.\n\nis_support is false for: marketing newsletters and digests, automated receipts and invoices from suppliers, recruiters and job applications, cold sales pitches and link-building or SEO offers, internal team mail (standups, sprint notes, all-hands), calendar and delivery notifications, out-of-office replies, and spam.\n\nconfidence is your own calibrated probability that this decision is correct. Be conservative. If the message mixes topics, is ambiguous, is written by an angry customer, or you cannot tell what is being asked, return a confidence below 0.6.\n\ntouches_money must be true for anything that could move money or change a contract: refunds, chargebacks, cancellations with money attached, discount requests, price disputes, duplicate charges, invoices the sender wants changed, or anything legal.\n\nreason is one short sentence explaining the decision in terms a human reviewing the log would accept."
    },
    {
      "role": "user",
      "content": {{ JSON.stringify('From: ' + $json.sender + '\nSubject: ' + $json.subject + '\n\n' + $json.body.slice(0, 4000)) }}
    }
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "support_classification",
      "strict": true,
      "schema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "is_support",
          "intent",
          "confidence",
          "touches_money",
          "reason"
        ],
        "properties": {
          "is_support": {
            "type": "boolean"
          },
          "intent": {
            "type": "string",
            "enum": [
              "product_question",
              "billing_question",
              "billing_dispute",
              "bug_report",
              "account_access",
              "other_support",
              "newsletter",
              "invoice_or_receipt",
              "recruiting",
              "sales_pitch",
              "internal",
              "spam",
              "other_non_support"
            ]
          },
          "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1
          },
          "touches_money": {
            "type": "boolean"
          },
          "reason": {
            "type": "string"
          }
        }
      }
    }
  }
}

