// Three attempts, all failed. The safe default when triage is impossible is to
// treat the mail as support that needs a person: an unanswered customer is
// recoverable, an auto-reply built on a guess is not. touches_money is forced
// true so the gate downstream cannot auto-answer it whatever the engine says.
const email = $('Restore Email Context').first().json;
const failure = $input.first().json?.error ?? {};

return [
  {
    json: {
      ...email,
      is_support: true,
      intent: 'other_support',
      classifier_confidence: 0,
      touches_money: true,
      caution_reason: 'classifier unavailable - defaulted to human review',
      classification_reason: 'the classifier could not be reached',
      integration_error: 'Classify: Support Or Not - ' + String(failure.message || failure.description || 'unavailable').slice(0, 300),
    },
  },
];

// The model classifies; the keyword sweep audits it, in one direction only.
//
// A sweep that could LOWER caution would be a way to talk the gate into
// answering a refund request by phrasing it carefully. So every rule here can
// set touches_money to true or pull confidence down, and none of them can do
// the opposite. If the model says "no money involved" and the customer wrote
// the word "chargeback", the customer wins.
const email = $('Restore Email Context').first().json;
const raw = $input.first().json;

const content = raw?.choices?.[0]?.message?.content;
if (typeof content !== 'string') {
  throw new Error(
    'The classifier endpoint did not return a chat completion. Body began: ' +
      JSON.stringify(raw).slice(0, 300),
  );
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (err) {
  throw new Error('The classifier returned content that is not JSON: ' + content.slice(0, 300));
}

const cautions = [];
let confidence = Number(parsed.confidence);
if (!Number.isFinite(confidence)) confidence = 0;

if (email.keyword_money) cautions.push('money keywords: ' + email.keyword_hits.join(', '));
if (email.keyword_legal) cautions.push('legal keywords');
if (email.keyword_angry) cautions.push('angry language');

// An angry customer is still a support request, but not one a bot should take
// the first swing at. Capping rather than zeroing keeps the number honest in
// the decision log.
if (email.keyword_angry) confidence = Math.min(confidence, 0.5);

return [
  {
    json: {
      ...email,
      is_support: parsed.is_support === true,
      intent: String(parsed.intent || 'other_support'),
      classifier_confidence: Math.round(confidence * 1000) / 1000,
      touches_money: parsed.touches_money === true || email.keyword_money || email.keyword_legal,
      classification_reason: String(parsed.reason || '').slice(0, 400),
      caution_reason: cautions.join('; ') || null,
      integration_error: null,
    },
  },
];

// Reached from both outputs of the label node, so the row is written whether or
// not Gmail accepted the label. A decision log missing exactly the decisions
// that went wrong is worse than no decision log.
const email = $('Apply Keyword Sweep').first().json;
const arrived = $input.first().json ?? {};
const labelFailed = Boolean(arrived.error);

return [
  {
    json: {
      decision_key: email.decision_key,
      channel: 'email',
      from_address: email.sender,
      subject: email.subject,
      conversation_ref: email.thread_id,
      intent: email.intent,
      is_support: false,
      confidence: email.classifier_confidence,
      grounded: false,
      touches_money: email.touches_money,
      action: 'routed_out_not_support',
      inbound_text: email.body,
      reply_text: null,
      used_article_ids: [],
      reason: email.classification_reason,
      integration_error: labelFailed
        ? 'Label As Not Support - ' + String(arrived.error?.message || 'failed').slice(0, 300)
        : null,
      execution_id: String($execution.id),
    },
  },
];

// The call into the shared backend. Both channels build this same shape, which
// is the point: there is one place that knows how to answer a question, and two
// places that know how to receive one.
const email = $('Apply Keyword Sweep').first().json;

// Both sides of the conversation, in order. The customer's own earlier words
// are what make a follow-up retrievable; the agent's earlier answers are what
// stop it repeating itself.
const history = $input
  .all()
  .map((i) => i.json)
  .filter((row) => row && row.created_at)
  .flatMap((row) => [
    ...(row.inbound_text ? [{ role: 'visitor', content: row.inbound_text }] : []),
    ...(row.reply_text ? [{ role: 'agent', content: row.reply_text }] : []),
  ]);

return [
  {
    json: {
      ...email,
      channel: 'email',
      text: email.body,
      session_or_thread_id: email.thread_id,
      history,
      history_turns: history.length,
    },
  },
];

// The engine returns what it knows about the ANSWER. The classification knows
// what the message is. The gate below needs both, in one item.
const context = $('Build Engine Request').first().json;
const result = $input.first().json ?? {};

return [
  {
    json: {
      ...context,
      grounded: result.grounded === true,
      answer: result.answer ?? null,
      // Two independent confidences, and the gate must clear the lower of them.
      // A confident classification of a question the knowledge base half-answers
      // is not a confident answer.
      answer_confidence: Number(result.confidence ?? 0),
      confidence: Math.min(Number(context.classifier_confidence ?? 0), Number(result.confidence ?? 0)),
      used_article_ids: result.used_article_ids ?? [],
      escalate_reason: result.escalate_reason ?? null,
      times_asked: result.times_asked ?? null,
      integration_error: context.integration_error || result.integration_error || null,
    },
  },
];

const context = $('Combine Answer And Classification').first().json;
const sent = $('Reply In The Same Thread').first().json ?? {};
const arrived = $input.first().json ?? {};
const labelFailed = Boolean(arrived.error);

return [
  {
    json: {
      decision_key: context.decision_key,
      channel: 'email',
      from_address: context.sender,
      subject: context.subject,
      conversation_ref: context.thread_id,
      intent: context.intent,
      is_support: true,
      confidence: context.confidence,
      grounded: true,
      touches_money: context.touches_money,
      action: 'auto_replied',
      inbound_text: context.body,
      reply_text: context.answer,
      used_article_ids: context.used_article_ids,
      reason: 'answered from articles ' + (context.used_article_ids || []).join(', '),
      integration_error: labelFailed
        ? 'Label As Auto Replied - ' + String(arrived.error?.message || 'failed').slice(0, 300)
        : null,
      execution_id: String($execution.id),
      sent_thread_id: sent.threadId ?? null,
    },
  },
];

// Gmail refused the reply three times. The answer was good; the delivery was
// not. That is a handover, not a retry loop, and the customer is now waiting.
const context = $('Combine Answer And Classification').first().json;
const failure = $input.first().json?.error ?? {};

return [
  {
    json: {
      ...context,
      escalate_reason: 'reply_delivery_failed',
      handover_reason: 'The agent had an answer but Gmail rejected the reply three times.',
      integration_error: 'Reply In The Same Thread - ' + String(failure.message || failure.description || 'failed').slice(0, 300),
    },
  },
];

// Every route to a human passes through here, so the reason a customer did not
// get an automated answer is written once and is always in the same words.
const context = $input.first().json;

const reasons = {
  no_matching_article: 'The knowledge base has no article covering this question.',
  not_answerable_from_kb: 'Articles were found but none of them answer this question.',
  answer_engine_unavailable: 'The answer engine could not be reached.',
  reply_delivery_failed: 'The agent had an answer but Gmail rejected the reply.',
};

let reason;
if (context.touches_money) {
  reason = 'Touches money or legal matters - never auto-answered, whatever the confidence.';
} else if (context.handover_reason) {
  reason = context.handover_reason;
} else if (context.escalate_reason && reasons[context.escalate_reason]) {
  reason = reasons[context.escalate_reason];
} else if (!context.grounded) {
  reason = 'No grounded answer was produced.';
} else {
  reason = 'Confidence ' + context.confidence + ' is below the threshold ' + ($env.SUPPORT_CONFIDENCE_THRESHOLD || '?') + '.';
}

return [
  {
    json: {
      ...context,
      handover_reason: reason,
      slack_payload: {
        text: 'Support email needs a human: ' + context.subject,
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: 'Support email needs a human' } },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: '*From*\n' + context.sender },
              { type: 'mrkdwn', text: '*Subject*\n' + String(context.subject).slice(0, 140) },
              { type: 'mrkdwn', text: '*Confidence*\n' + context.confidence },
              { type: 'mrkdwn', text: '*Touches money*\n' + (context.touches_money ? 'yes' : 'no') },
            ],
          },
          { type: 'section', text: { type: 'mrkdwn', text: '*Why a human*\n' + reason } },
          { type: 'section', text: { type: 'mrkdwn', text: '*Question*\n' + String(context.body || '').slice(0, 900) } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: 'Gmail thread ' + context.thread_id + ' - labelled Support/Needs-Human' }] },
        ],
      },
    },
  },
];

const context = $('Build Handover').first().json;
const arrived = $input.first().json ?? {};
const slackFailed = Boolean(arrived.error);

return [
  {
    json: {
      decision_key: context.decision_key,
      channel: 'email',
      from_address: context.sender,
      subject: context.subject,
      conversation_ref: context.thread_id,
      intent: context.intent,
      is_support: true,
      confidence: context.confidence,
      grounded: context.grounded === true,
      touches_money: context.touches_money,
      action: 'handed_to_human',
      inbound_text: context.body,
      reply_text: null,
      used_article_ids: context.used_article_ids || [],
      reason: context.handover_reason,
      integration_error: [
        context.integration_error,
        slackFailed ? 'Alert The Review Channel - ' + String(arrived.error?.message || 'failed').slice(0, 200) : null,
      ].filter(Boolean).join(' | ') || null,
      execution_id: String($execution.id),
    },
  },
];
